#!/usr/bin/env node
"use strict";

// Development-only vendor refresh. Input is the integrity-verified, extracted
// prismjs npm package described in prism.md; deployments run the committed files.
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const vm = require("node:vm");
const source = path.resolve(process.argv[2] || "");
if (!process.argv[2])
  throw new Error(
    "Usage: node .conf/vendor/vendor-prism.cjs /path/to/prismjs/package",
  );
const version = "1.30.0";
const metadata = JSON.parse(
  fs.readFileSync(path.join(source, "package.json"), "utf8"),
);
if (metadata.name !== "prismjs" || metadata.version !== version)
  throw new Error(
    `Expected prismjs ${version}. Review the pinned version before updating.`,
  );
const components = require(path.join(source, "components.json"));
const getLoader = require(path.join(source, "dependencies.js"));
const ids = Object.keys(components.languages).filter((id) => id !== "meta");
const order = [];
// Use upstream's complete dependency resolver, including optional/modify edges.
// Alphabetical concatenation breaks embedded grammars and is not equivalent.
getLoader(components, ids, []).load((id) => order.push(id));
const header = `/*! PrismJS ${version} | MIT | https://prismjs.com | See LICENSE.\n * Core and all ${ids.length} official language components; generated by .conf/vendor/vendor-prism.cjs.\n */\n`;
const bundle =
  header +
  "globalThis.Prism = { manual: true, disableWorkerMessageHandler: true };\n" +
  ["core", ...order]
    .map(
      (id) =>
        `\n/* Component: ${id} */\n${fs.readFileSync(path.join(source, "components", `prism-${id}.min.js`), "utf8")}\n`,
    )
    .join(";");

// Check every registered component before replacing the committed artifacts.
// A tiny browser-shaped context avoids any DOM scanning; the application runs
// Prism in its own worker and owns timeouts/message handling.
const context = vm.createContext({ console });
vm.runInContext("globalThis.window = globalThis", context);
vm.runInContext(bundle, context, { timeout: 5000 });
const sample =
  '<root attr="a&b">{ "ok": true, "n": 123 }</root>\nconst x = 42; // sample\n';
const notSelectable = new Set([
  "css-extras",
  "js-extras",
  "js-templates",
  "php-extras",
  "xml-doc",
  "markup-templating",
  "t4-templating",
]);
for (const id of ids) {
  if (notSelectable.has(id)) continue; // Helpers used by grammars, not grammars themselves.
  if (!context.Prism.languages[id])
    throw new Error(`Missing Prism component: ${id}`);
  const result = vm.runInContext(
    `Prism.highlight(${JSON.stringify(sample)}, Prism.languages[${JSON.stringify(id)}], ${JSON.stringify(id)})`,
    context,
    { timeout: 1500 },
  );
  if (typeof result !== "string")
    throw new Error(`Invalid Prism output: ${id}`);
}
const languages = ids
  .filter((id) => !notSelectable.has(id))
  .map((id) => {
    const item = components.languages[id];
    return {
      id,
      name: typeof item === "string" ? item : item.title,
      aliases: item.alias ? [].concat(item.alias) : [],
    };
  })
  .sort((a, b) =>
    a.name.toLowerCase() < b.name.toLowerCase()
      ? -1
      : a.name.toLowerCase() > b.name.toLowerCase()
        ? 1
        : a.id < b.id
          ? -1
          : 1,
  );
const out = path.resolve(__dirname, "../../assets/vendor/prism");
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "prism.js"), bundle);
fs.writeFileSync(
  path.join(out, "languages.json"),
  JSON.stringify(languages, null, 2) + "\n",
);
fs.writeFileSync(
  path.join(out, "languages.js"),
  `/*! PrismJS ${version} language metadata | MIT | See LICENSE. */\n"use strict";\nglobalThis.SyntaxLanguages = ${JSON.stringify(languages)};\n`,
);
fs.copyFileSync(path.join(source, "LICENSE"), path.join(out, "LICENSE"));
const sums =
  ["LICENSE", "languages.js", "languages.json", "prism.js"]
    .map(
      (file) =>
        `${crypto
          .createHash("sha256")
          .update(fs.readFileSync(path.join(out, file)))
          .digest("hex")}  ${file}`,
    )
    .join("\n") + "\n";
fs.writeFileSync(path.join(out, "SHA256SUMS"), sums);
console.log(
  `Vendored Prism ${version}: ${ids.length} components, ${languages.length} selectable languages, ${bundle.length} source characters.`,
);
